using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEngine.InputSystem;public class HintManager : MonoBehaviour{    [Header("Hint Settings")]    public float fadeInTime = 1f;    public float fadeOutTime = 1f;    [Header("Player References")]    public Camera player1Camera;    public Camera player2Camera;    public Volume player1Volume;    public Volume player2Volume;    public float vignetteIntensity = 0.31f;    [Header("Input")]    [SerializeField] private string hintActionPath = "Gameplay/Hint";    [Header("Overlay")]    [SerializeField] private int overlayRendererIndex = 1;    [Tooltip("Layer name used by overlays to render hints only")] public string overlaySaturationLayerName = "Saturation_Layer";    private int overlaySaturationLayer = -1;    [Header("Dialogue Tutorial")]    [SerializeField] private bool dialoguePlayed = false;    [SerializeField] private string dialogueName = "";    private Vignette p1Vignette;    private Vignette p2Vignette;    private ColorAdjustments p1Color;    private ColorAdjustments p2Color;    private float p1EffectWeight = 0f;    private float p2EffectWeight = 0f;    private TwoPlayerInput p1Controls;    private TwoPlayerInput p2Controls;    private InputAction p1HintAction;    private InputAction p2HintAction;    private bool p1HintHeld;    private bool p2HintHeld;    void OnValidate()    {#if UNITY_EDITOR        overlayRendererIndex = 1;#endif    }    void Start()    {        SetupInputBindings();        if (player1Volume != null && player1Volume.profile != null)        {            player1Volume.profile.TryGet(out p1Vignette);            player1Volume.profile.TryGet(out p1Color);        }        if (player2Volume != null && player2Volume.profile != null)        {            player2Volume.profile.TryGet(out p2Vignette);            player2Volume.profile.TryGet(out p2Color);        }        if (p1Vignette != null) { p1Vignette.intensity.overrideState = true; p1Vignette.intensity.value = 0f; }        if (p2Vignette != null) { p2Vignette.intensity.overrideState = true; p2Vignette.intensity.value = 0f; }        if (p1Color != null) { p1Color.saturation.overrideState = true; p1Color.saturation.value = 0f; }        if (p2Color != null) { p2Color.saturation.overrideState = true; p2Color.saturation.value = 0f; }        overlaySaturationLayer = LayerMask.NameToLayer(overlaySaturationLayerName);    }    private void SetupInputBindings()    {        var playerManager = PlayerInputManager.Instance;        if (playerManager == null)        {            return;        }        p1Controls = playerManager.Player1Controls;        p2Controls = playerManager.Player2Controls;        p1HintAction = FindActionSafe(p1Controls, hintActionPath);        if (p1HintAction != null)        {            p1HintAction.started += OnP1HintStarted;            p1HintAction.performed += OnP1HintStarted;            p1HintAction.canceled += OnP1HintCanceled;        }        p2HintAction = FindActionSafe(p2Controls, hintActionPath);        if (p2HintAction != null)        {            p2HintAction.started += OnP2HintStarted;            p2HintAction.performed += OnP2HintStarted;            p2HintAction.canceled += OnP2HintCanceled;        }    }    private static InputAction FindActionSafe(TwoPlayerInput controls, string actionPath)    {        if (controls == null || controls.asset == null) return null;        return controls.asset.FindAction(actionPath, false);    }    private void OnP1HintStarted(InputAction.CallbackContext context)    {        p1HintHeld = true;        CallGlowDialogue();    }    private void OnP1HintCanceled(InputAction.CallbackContext context)    {        p1HintHeld = false;    }    private void OnP2HintStarted(InputAction.CallbackContext context)    {        p2HintHeld = true;        CallGlowDialogue();    }    private void OnP2HintCanceled(InputAction.CallbackContext context)    {        p2HintHeld = false;    }    void Update()    {        var pm = PlayerInputManager.Instance;        var kb = Keyboard.current;        bool shift = kb != null && kb.shiftKey.isPressed;        if (pm != null && pm.CurrentControllerType == PlayerInputManager.ControllerType.SinglePlayer)        {            if (pm.CurrPlayerEnum == BasePlayerController.PlayerID.Player1)            {                p1HintHeld = (p1HintAction != null && p1HintAction.IsPressed()) || shift;                p2HintHeld = false;            }            else            {                p1HintHeld = false;                p2HintHeld = (p2HintAction != null && p2HintAction.IsPressed()) || shift;            }        }        else        {            p1HintHeld = (p1HintAction != null && p1HintAction.IsPressed());            p2HintHeld = (p2HintAction != null && p2HintAction.IsPressed());        }        float p1Duration = p1HintHeld ? fadeInTime : fadeOutTime;        float p2Duration = p2HintHeld ? fadeInTime : fadeOutTime;        float p1Target = p1HintHeld ? 1f : 0f;        float p2Target = p2HintHeld ? 1f : 0f;        p1EffectWeight = Mathf.MoveTowards(p1EffectWeight, p1Target, Time.unscaledDeltaTime / Mathf.Max(0.0001f, p1Duration));        p2EffectWeight = Mathf.MoveTowards(p2EffectWeight, p2Target, Time.unscaledDeltaTime / Mathf.Max(0.0001f, p2Duration));        float t1 = p1EffectWeight * p1EffectWeight * (3f - 2f * p1EffectWeight);        float t2 = p2EffectWeight * p2EffectWeight * (3f - 2f * p2EffectWeight);        if (p1Vignette != null) p1Vignette.intensity.value = t1 * vignetteIntensity;        if (p2Vignette != null) p2Vignette.intensity.value = t2 * vignetteIntensity;        float p1Sat = Mathf.Lerp(0f, -100f, t1);        float p2Sat = Mathf.Lerp(0f, -100f, t2);        if (p1Color != null) p1Color.saturation.value = p1Sat;        if (p2Color != null) p2Color.saturation.value = p2Sat;        EnsureOverlaySettings(player1Camera);        EnsureOverlaySettings(player2Camera);    }    private void EnsureOverlaySettings(Camera baseCam)    {        if (baseCam == null) return;        var baseData = baseCam.GetComponent<UnityEngine.Rendering.Universal.UniversalAdditionalCameraData>();        if (baseData == null) return;        var stack = baseData.cameraStack;        for (int i = 0; i < stack.Count; i++)        {            var overlay = stack[i];            if (overlay == null) continue;            var overlayData = overlay.GetComponent<UnityEngine.Rendering.Universal.UniversalAdditionalCameraData>();            if (overlayData == null) continue;            overlayData.renderType = CameraRenderType.Overlay;            overlayData.renderPostProcessing = false;            overlayData.volumeLayerMask = 0;            overlayData.SetRenderer(overlayRendererIndex);            if (overlaySaturationLayer != -1)            {                overlay.cullingMask = 1 << overlaySaturationLayer;            }        }    }    private void CallGlowDialogue()    {        if (dialoguePlayed)        {            return;        }        if (!string.IsNullOrEmpty(dialogueName) && DialogueManager.Instance != null)        {            DialogueManager.Instance.StartDialogue(dialogueName);        }        dialoguePlayed = true;    }    private void OnDestroy()    {        if (p1HintAction != null)        {            p1HintAction.started -= OnP1HintStarted;            p1HintAction.performed -= OnP1HintStarted;            p1HintAction.canceled -= OnP1HintCanceled;        }        if (p2HintAction != null)        {            p2HintAction.started -= OnP2HintStarted;            p2HintAction.performed -= OnP2HintStarted;            p2HintAction.canceled -= OnP2HintCanceled;        }    }}